import{_ as s,o as c,a as n,b as e}from"./app.DKoEZOcr.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"基础定义","link":"/api/SIMD-API/c_api/defs/defs"},{"text":"枚举","link":"/api/SIMD-API/c_api/defs/enum/enum"},{"text":"asc_load_l2_cache_mode","link":"/api/SIMD-API/c_api/defs/enum/asc_load_l2_cache_mode"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/defs/enum/asc_load_l2_cache_mode.md","filePath":"api/SIMD-API/c_api/defs/enum/asc_load_l2_cache_mode.md","outlineHeaders":[{"level":2,"title":"枚举类具体定义","slug":"枚举类具体定义","link":"#枚举类具体定义"},{"level":2,"title":"枚举值详解","slug":"枚举值详解","link":"#枚举值详解"}],"lastUpdated":1787999811000}'),p={name:"api/SIMD-API/c_api/defs/enum/asc_load_l2_cache_mode.md"};function l(t,a,_,d,h,i){return c(),n("div",null,[...a[0]||(a[0]=[e(`<div><article class="markdown-body"><h1>asc_load_l2_cache_mode</h1><p>asc_load_l2_cache_mode用于表示数据从GM搬运到Unified Buffer（UB）时的L2 cache管理策略，可用于：</p><ul><li>向量搬运接口，例如<a href="../../vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a>和<a href="../../vector_datamove/asc_ndim_copy_gm2ub.html">asc_ndim_copy_gm2ub</a>。</li><li>标量访存路径的load策略配置与查询，例如<a href="../../cache_ctrl/asc_set_scalar_cache_mode.html">asc_set_scalar_cache_mode</a>和<a href="../../cache_ctrl/asc_get_scalar_load_cache_mode.html">asc_get_scalar_load_cache_mode</a>。</li></ul><p>L2 Cache管理策略的影响可见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/02_features/00_data_movement/00_set_l2_cache_mode/README.md">L2 Cache Mode最佳实践</a>。</p><h2 id="枚举类具体定义">枚举类具体定义<a class="header-anchor" href="#枚举类具体定义">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">enum</span><span class="w"> </span><span class="k">class</span><span class="w"> </span><span class="nc">asc_load_l2_cache_mode</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">NORMAL_FIRST_VICTIM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">NORMAL_LAST_VICTIM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">    </span><span class="n">NORMAL_PERSISTENT</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span>
<span class="w">    </span><span class="n">NOTALLOC_KEEP</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span>
<span class="w">    </span><span class="n">NOTALLOC_CLEAN</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">,</span>
<span class="w">    </span><span class="n">NOTALLOC_DROP</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span>
<span class="p">};</span>
</code></pre></div><h2 id="枚举值详解">枚举值详解<a class="header-anchor" href="#枚举值详解">​</a></h2><p><strong>表1</strong> 枚举值说明</p><table><thead><tr><th>枚举值</th><th>L2 cache管理策略</th></tr></thead><tbody><tr><td>NORMAL_FIRST_VICTIM</td><td>启用L2 Cache，并且将分配的Cache Line标记为高替换优先级。</td></tr><tr><td>NORMAL_LAST_VICTIM</td><td>启用L2 Cache，并且将分配的Cache Line标记为低替换优先级。</td></tr><tr><td>NORMAL_PERSISTENT</td><td>启用L2 Cache。已存入L2 Cache中的数据可能被替换，若需确保特定数据始终保留在L2 Cache中，可采用驻留模式。<br>• 注意，被标记为驻留模式的Cache Line只能被其他同样被标记为驻留模式的Cache Line替换。</td></tr><tr><td>NOTALLOC_KEEP</td><td>不启用L2 Cache，每次都直接从GM中读取，并且保持已有Cache Line的状态不变。</td></tr><tr><td>NOTALLOC_CLEAN</td><td>不启用L2 Cache，若L2 Cache中已有同地址缓存会被保留并标记为Clean，标记为Clean的Cache Line被移出L2 Cache时会被直接丢弃。</td></tr><tr><td>NOTALLOC_DROP</td><td>不启用L2 Cache，若L2 Cache中已有同地址缓存，会被直接丢弃。</td></tr></tbody></table></article></div>`,1)])])}const m=s(p,[["render",l]]);export{r as __pageData,m as default};
